-- ===========================================================================
-- analytics.kalman_filtered_price_targets_v2
-- ===========================================================================
-- Generated by pymc_kalman_filter_pt_v2.py -- do not hand-edit; it is rewritten
-- on every export.
--
-- UNITS: all return-like columns are RAW DECIMALS (0.25 = +25%), per the
-- 0.9.9.7 convention. Percent scaling happens only at display boundaries.
--
-- This is the **v2** table. v1 continues to write
-- analytics.kalman_filtered_price_targets, which is what the GEIB dashboard
-- reads; the two coexist so the models can be compared on one database.
-- Promoting v2 means repointing the dashboard, not renaming this table.
-- ===========================================================================

DROP TABLE IF EXISTS analytics."kalman_filtered_price_targets_v2";
CREATE TABLE analytics."kalman_filtered_price_targets_v2"
(
    "isin" TEXT,
    "ticker" TEXT,
    "name" TEXT,
    "sector" TEXT,
    "industry" TEXT,
    "trading_region" TEXT,
    "country" TEXT,
    "style_class" TEXT,
    "size_class" TEXT,
    "n_analysts" DOUBLE PRECISION,
    "market_cap" DOUBLE PRECISION,
    "mcap_global_r" DOUBLE PRECISION,
    "mcap_country_r" DOUBLE PRECISION,
    "original_price" DOUBLE PRECISION,
    "original_target" DOUBLE PRECISION,
    "expected_return_kalman" DOUBLE PRECISION,
    "expected_upside_sd" DOUBLE PRECISION,
    "prob_pos" DOUBLE PRECISION,
    "implied_upside" DOUBLE PRECISION,
    "price_target_kalman" DOUBLE PRECISION,
    "expected_pt_hdi_lo" DOUBLE PRECISION,
    "expected_pt_hdi_hi" DOUBLE PRECISION,
    "risk_adj_return" DOUBLE PRECISION,
    "kalman_gain" DOUBLE PRECISION,
    "er_mean" DOUBLE PRECISION,
    "er_sd" DOUBLE PRECISION,
    "er_p05" DOUBLE PRECISION,
    "er_p50" DOUBLE PRECISION,
    "er_p95" DOUBLE PRECISION,
    "mc_prob_pos" DOUBLE PRECISION,
    "p_upside_pos" DOUBLE PRECISION,
    "band_width" DOUBLE PRECISION,
    "p_upside_pos_cond" DOUBLE PRECISION,
    "cvar_5pct_kalman" DOUBLE PRECISION,
    "expected_vol_kalman" DOUBLE PRECISION,
    "ret_vol_ratio" DOUBLE PRECISION,
    "expected_sharpe_ratio" DOUBLE PRECISION,
    "tail_risk" DOUBLE PRECISION,
    "reward_to_cvar" DOUBLE PRECISION,
    "cvar_book_weight" DOUBLE PRECISION,
    "out_of_support" BOOLEAN,
    "run_id" TEXT,
    "exported_at" TEXT
);

COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."expected_return_kalman" IS
    'Posterior mean expected upside. Raw decimal (0.25 = +25%).';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."prob_pos" IS
    'Share of the per-name posterior above zero. REPORTED, NOT RANKED: the smoother is Rao-Blackwellised over the latent, so this saturates at 1.0 for most of the universe (87.5% on run fa532b925732) and cannot order anything. Rank on p_upside_pos_cond instead. Retained because the share itself is a legitimate per-name statement; the prob_pos_degenerate gate warns when it stops discriminating.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."implied_upside" IS
    'Analyst consensus upside, original_target/original_price - 1. Raw decimal.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."price_target_kalman" IS
    'Smoothed price target, in the security''s own currency.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."kalman_gain" IS
    'Posterior mean achieve_prob = sigmoid(risk_adj_return).';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."er_mean" IS
    'Mean forward return over the Monte-Carlo horizon. Raw decimal.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."er_sd" IS
    'Pooled sd of the forward-return draws. Denominator of expected_sharpe_ratio.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."er_p05" IS
    '5th percentile forward return. Drives the upper out_of_support test.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."er_p95" IS
    '95th percentile forward return. Drives the lower out_of_support test.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."mc_prob_pos" IS
    'Share of Monte-Carlo forward-return draws above zero.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."p_upside_pos_cond" IS
    'mc_prob_pos * kalman_gain. The probability column that actually orders names -- prefer it to prob_pos, which is pinned at 1.0 for most of the universe and cannot rank.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."cvar_5pct_kalman" IS
    'Conditional mean of the worst 5% of the expected-upside posterior. This is a RETURN LEVEL, not a loss: it is positive for most names because most names have an entirely positive upside posterior. Raw decimal. For a dispersion measure use reward_to_cvar''s denominator.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."expected_vol_kalman" IS
    'Posterior dispersion of expected upside (~2-3%), NOT equity return volatility. Raw decimal.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."expected_sharpe_ratio" IS
    'er_mean / er_sd over Monte-Carlo draws of log price-target uplift. A t-statistic on the distance from price to the smoothed target, NOT an investment Sharpe ratio -- the denominator is parameter uncertainty, not realised return volatility. NULL when out_of_support.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."reward_to_cvar" IS
    'expected_return_kalman / tail_risk (STARR). NULL when out_of_support.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."cvar_book_weight" IS
    'Weight in the CVaR-sized book, 0 outside it and 0 when out_of_support.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."out_of_support" IS
    'TRUE when the forward-return distribution is pinned at a clip bound (er_p05 at the +500% cap or er_p95 at the -95% floor). Ranking metrics are NULL for these rows; identity and the raw er_* distribution are kept.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."run_id" IS
    'Export provenance. Every table written by one run shares it.';
COMMENT ON COLUMN analytics."kalman_filtered_price_targets_v2"."exported_at" IS
    'Export provenance timestamp (UTC).';

CREATE UNIQUE INDEX IF NOT EXISTS idx_kalman_filtered_price_targets_v2_isin
    ON analytics."kalman_filtered_price_targets_v2" (isin);
